<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Receipt</title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;margin:0;padding:28px;color:#172033}.actions{text-align:center;margin-bottom:18px}.actions button,.actions a{display:inline-block;padding:10px 16px;border:0;border-radius:7px;background:#123b73;color:#fff;text-decoration:none;margin:0 4px;cursor:pointer}.receipt{max-width:720px;margin:auto;background:white;border:1px solid #cbd5e1;padding:34px}.head{text-align:center;border-bottom:2px solid #123b73;padding-bottom:18px}.head h1{margin:0;color:#123b73}.head p{margin:5px}.tag{text-align:center;font-size:20px;font-weight:bold;letter-spacing:2px;margin:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.cell{border-bottom:1px solid #e2e8f0;padding:9px}.label{display:block;color:#64748b;font-size:12px;margin-bottom:4px}.amount{background:#eff6ff;padding:16px;border-radius:10px;display:flex;justify-content:space-between;font-weight:bold}.foot{margin-top:45px;display:flex;justify-content:space-between;font-size:12px}@media print{body{background:white;padding:0}.actions{display:none}.receipt{border:0;max-width:none}@page{margin:15mm}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save PDF</button><a href="<?php echo e(route('payments.index')); ?>">Back</a></div><main class="receipt"><header class="head"><h1>TMSS POLYTECHNIC INSTITUTE</h1><p>Rangpur · TPIR</p><p>Official Payment Receipt</p></header><div class="tag">PAYMENT RECEIPT</div><div class="grid"><div class="cell"><span class="label">Receipt / Payment ID</span><b>TPIR-<?php echo e(str_pad($payment->id,6,'0',STR_PAD_LEFT)); ?></b></div><div class="cell"><span class="label">Payment Date</span><b><?php echo e($payment->paid_date?->format('d M Y')??'—'); ?></b></div><div class="cell"><span class="label">Student Name</span><b><?php echo e($payment->student?->name??'—'); ?></b></div><div class="cell"><span class="label">Student Roll</span><b><?php echo e($payment->student?->student_id??'—'); ?></b></div><div class="cell"><span class="label">Technology / Semester</span><b><?php echo e($payment->student?->technology); ?> / <?php echo e($payment->student?->semester); ?></b></div><div class="cell"><span class="label">Session</span><b><?php echo e($payment->student?->session??'—'); ?></b></div><div class="cell"><span class="label">Fee Description</span><b><?php echo e($payment->title); ?></b></div><div class="cell"><span class="label">Payment Method</span><b><?php echo e($payment->method??'—'); ?></b></div></div><div class="amount"><span>Amount Received</span><span>BDT <?php echo e(number_format($payment->amount_paid,2)); ?></span></div><div class="grid"><div class="cell"><span class="label">Total Fee</span><b>৳<?php echo e(number_format($payment->amount_due,2)); ?></b></div><div class="cell"><span class="label">Remaining Due</span><b>৳<?php echo e(number_format($payment->due,2)); ?></b></div><div class="cell" style="grid-column:1/-1"><span class="label">Note / Transaction ID</span><b><?php echo e($payment->note??'—'); ?></b></div></div><div class="foot"><span>Received by: __________________</span><span>Authorized Signature: __________________</span></div></main></body></html>
